import { Order } from './types';

export interface CursorPair {
  createdAt: string;
  id: string;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  // Slots a cursor pair into the tenant's ascending (createdAt, id) order and
  // returns every matching row strictly after it. Filtering by tenant happens
  // first, so a cursor pair from another tenant still yields this tenant's
  // later rows instead of shifting the offset in the raw input.
  list(tenant: string, after?: CursorPair): Order[] {
    const tenantRows = this.rows.filter(row => row.tenant === tenant);
    tenantRows.sort(compareOrders);
    if (!after) return tenantRows;
    return tenantRows.filter(row => compareOrders(row, after as ...) > 0);
  }
}

function compareOrders(a: {createdAt: string; id: string}, b: {createdAt: string; id: string}): number {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  if (a.id !== b.id) return a.id < b.id ? -1 : 1;
  return 0;
}
```

