import { OrderRepository } from './repository';
import { CursorPair, ListRequest, Page } from './types';

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}
  list(request: ListRequest): Page {
    if (!request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      throw new Error('invalid request');
    }
    const after = parseCursor(request.cursor);
    const rows = this.repository.list(request.tenant, after);
    const items = rows.slice(0, request.limit);
    const last = items[items.length - 1];
    return {
      items,
      // The literal 'createdAt|id' of the last returned order, or null once
      // no further matching order exists.
      nextCursor: last && rows.length > items.length ? `${last.createdAt}|${last.id}` : null,
    };
  }
}

// A cursor must consist of exactly two nonempty '|'-separated parts
// (createdAt, id); ids and dates never contain '|'.
function parseCursor(cursor: string | undefined): CursorPair | undefined {
  if (cursor === undefined) return undefined;
  const parts = typeof cursor === 'string' ? cursor.split('|') : [];
  if (parts.length !== 2 || parts[0] === '' || parts[1] === '') {
    throw new Error('invalid request');
  }
  return { createdAt: parts[0], id: parts[1] };
}
